import numpy as np

# Implementasi Star Schema Join & Analisis Aditivitas Fakta (Fully Additive vs Semi-Additive)
class StarSchemaWarehouse:
    def __init__(self):
        self.dim_customer = {
            1: {"name": "Budi", "segment": "Enterprise"},
            2: {"name": "Siti", "segment": "Retail"}
        }
        self.dim_date = {
            10: {"date": "2026-03-01", "day_name": "Minggu"},
            11: {"date": "2026-03-02", "day_name": "Senin"}
        }
        # Tabel Fakta: [date_fk, customer_fk, revenue (Additive), account_balance (Semi-Additive)]
        self.fact_table = [
            {"date_fk": 10, "cust_fk": 1, "revenue": 1000.0, "balance": 5000.0},
            {"date_fk": 11, "cust_fk": 1, "revenue": 1500.0, "balance": 6500.0},
            {"date_fk": 10, "cust_fk": 2, "revenue": 200.0,  "balance": 1200.0},
            {"date_fk": 11, "cust_fk": 2, "revenue": 300.0,  "balance": 1500.0},
        ]

    def execute_star_query(self, target_segment="Enterprise"):
        # Kueri: Agregasi pendapatan dan saldo akhir pelanggan Enterprise
        tot_rev = 0.0
        final_balances = {}

        for row in self.fact_table:
            cust = self.dim_customer[row["cust_fk"]]
            if cust["segment"] == target_segment:
                # Fully Additive: Pendapatan dapat diakumulasikan lintas hari
                tot_rev += row["revenue"]
                # Semi-Additive: Saldo hanya valid diambil pada stempel tanggal terakhir
                final_balances[row["cust_fk"]] = row["balance"]

        return tot_rev, sum(final_balances.values())

wh = StarSchemaWarehouse()
ent_rev, ent_bal = wh.execute_star_query("Enterprise")

print("Hasil Kueri Eksekusi Skema Bintang (Star Join):")
print(f"  Total Pendapatan Akumulasi (Fully Additive) : Rp {ent_rev:,.2f}")
print(f"  Saldo Akhir Efektif (Semi-Additive Point)   : Rp {ent_bal:,.2f}")
print("  Validasi Aditivitas: Saldo tidak dijumlahkan sembarangan melintasi hari (Konsistensi Terjaga!)")

import numpy as np

# Simulasi Drill-Across Query: Menggabungkan 2 Tabel Fakta via Dimensi Konform (Produk)
class EnterpriseBusWarehouse:
    def __init__(self):
        # Dimensi Konform (Dipakai Bersama oleh Divisi Sales & Divisi Inventory)
        self.dim_conformed_product = {
            101: "Laptop Gaming Pro",
            102: "Monitor UltraWide 34\""
        }
        # Fakta 1: Penjualan Harian (Divisi Sales)
        self.fact_sales = [
            {"prod_fk": 101, "revenue": 25_000_000.0},
            {"prod_fk": 101, "revenue": 25_000_000.0},
            {"prod_fk": 102, "revenue": 8_000_000.0}
        ]
        # Fakta 2: Stok Gudang Harian (Divisi Inventory)
        self.fact_inventory = [
            {"prod_fk": 101, "units_in_stock": 45},
            {"prod_fk": 102, "units_in_stock": 120}
        ]

    def execute_drill_across(self):
        # Langkah 1: Agregasi Fakta 1 per Dimensi Konform
        sales_agg = {}
        for s in self.fact_sales:
            sales_agg[s["prod_fk"]] = sales_agg.get(s["prod_fk"], 0.0) + s["revenue"]

        # Langkah 2: Agregasi Fakta 2 per Dimensi Konform
        inv_agg = {}
        for inv in self.fact_inventory:
            inv_agg[inv["prod_fk"]] = inv["units_in_stock"]

        # Langkah 3: Gabungkan (Drill-Across Join) pada tingkat Dimensi Konform
        report = []
        for prod_id, prod_name in self.dim_conformed_product.items():
            tot_rev = sales_agg.get(prod_id, 0.0)
            stock = inv_agg.get(prod_id, 0)
            report.append({"product": prod_name, "revenue": tot_rev, "stock": stock})
        return report

bus = EnterpriseBusWarehouse()
consolidated_report = bus.execute_drill_across()

print("Laporan Eksekutif Drill-Across Lintas Departemen (via Dimensi Konform):")
for r in consolidated_report:
    print(f"  Produk: {r['product']:<24} | Penjualan: Rp {r['revenue']:>12,.2f} | Sisa Stok: {r['stock']:3d} unit")
print("  Integritas Data: Zero Cartesian Explosion (Kueri mematuhi standar Kimball Bus Architecture!)")
